/*
 * Ionbit UI — Design Tokens
 *
 * Layered as:
 *   1. :root / .dark — raw semantic variable values (themeable by consumers)
 *   2. @theme inline — Tailwind v4 theme mapping (utilities resolve to the
 *      variables above)
 *
 * Components reference semantic utilities only (bg-surface, text-foreground,
 * border-border, etc.). Retheming = overriding the variables in :root / .dark.
 *
 * The default theme is dark, technical, and restrained. Not neon cyberpunk.
 */

/* ---------------------------------------------------------------------------
 * 1. Raw semantic token values
 * --------------------------------------------------------------------------- */

:root {
  /* The default theme is dark. These values ARE the dark theme. */
  color-scheme: dark;

  /* Surfaces — subtle brightness steps, not flat black. */
  --background: oklch(0.16 0.012 250); /* deep neutral, faintly cool */
  --surface: oklch(0.19 0.013 250);
  --surface-elevated: oklch(0.22 0.014 250);
  --surface-hover: oklch(0.235 0.015 250);

  /* Foreground — high but not pure-white contrast. */
  --foreground: oklch(0.96 0.005 250);
  --foreground-muted: oklch(0.68 0.012 250);
  --foreground-subtle: oklch(0.52 0.012 250);

  /* Borders — barely visible at rest, stronger on interaction. */
  --border: oklch(1 0 0 / 0.08);
  --border-strong: oklch(1 0 0 / 0.14);
  --border-accent: oklch(0.78 0.16 238 / 0.5);
  --border-error: oklch(0.62 0.24 5 / 0.5);

  /* Accent — electric cyan/blue family. Configurable. */
  --accent: oklch(0.78 0.17 238);
  --accent-hover: oklch(0.82 0.18 238);
  --accent-muted: oklch(0.78 0.17 238 / 0.16);
  --accent-foreground: oklch(0.1 0.02 238);

  /* Semantic status — restrained, not neon. */
  --success: oklch(0.78 0.15 155);
  --warning: oklch(0.82 0.15 80);
  --error: oklch(0.62 0.24 5);
  --error-foreground: oklch(0.1 0.04 5);
  --info: oklch(0.82 0.14 230);

  /* Focus ring — accent-tinted, visible but not loud. */
  --ring: oklch(0.82 0.16 238 / 0.55);

  /* Typography */
  --font-sans:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  --font-mono:
    ui-monospace, "SF Mono", "JetBrains Mono", "Fira Code", Menlo, Consolas,
    monospace;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;

  --leading-tight: 1.2;
  --leading-normal: 1.5;
  --leading-relaxed: 1.65;

  --tracking-tight: -0.01em;
  --tracking-normal: 0;
  --tracking-wide: 0.02em;

  --weight-normal: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;

  /* Spacing scale — 4px base. */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;

  /* Radius — controlled, not bubbly. */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-full: 9999px;

  /* Shadows — subtle, used for depth, not drama. */
  --shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 0.2);
  --shadow-sm:
    0 2px 4px -1px oklch(0 0 0 / 0.25), 0 1px 2px -1px oklch(0 0 0 / 0.2);
  --shadow-md:
    0 4px 8px -2px oklch(0 0 0 / 0.3), 0 2px 4px -2px oklch(0 0 0 / 0.25);
  --shadow-lg:
    0 12px 24px -8px oklch(0 0 0 / 0.4), 0 4px 8px -4px oklch(0 0 0 / 0.3);
  --shadow-glow:
    0 0 0 1px var(--border-accent),
    0 0 16px -4px color-mix(in oklab, var(--accent) 40%, transparent);
  --shadow-glow-error:
    0 0 0 1px var(--border-error),
    0 0 16px -4px color-mix(in oklab, var(--error) 40%, transparent);
  --shadow-focus: 0 0 0 2px var(--ring), 0 0 16px -4px var(--accent);
  --shadow-focus-error: 0 0 0 2px var(--error), 0 0 16px -4px var(--error);

  /* Motion — durations (ms) and easings. */
  --duration-fast: 140ms;
  --duration-normal: 220ms;
  --duration-slow: 420ms;
  --ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --ease-emphasized: cubic-bezier(0.3, 0, 0, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);

  /* Effect intensities — 0..1 multipliers. */
  --spotlight-intensity: 0.4;
  --magnetic-intensity: 0.25;
}

/* ---------------------------------------------------------------------------
 * Light theme override — architecture supports it; not the priority.
 * --------------------------------------------------------------------------- */

.light {
  color-scheme: light;

  --background: oklch(0.99 0.002 250);
  --surface: oklch(0.98 0.003 250);
  --surface-elevated: oklch(1 0 0);
  --surface-hover: oklch(0.96 0.004 250);

  --foreground: oklch(0.2 0.012 250);
  --foreground-muted: oklch(0.45 0.012 250);
  --foreground-subtle: oklch(0.6 0.012 250);

  --border: oklch(0 0 0 / 0.08);
  --border-strong: oklch(0 0 0 / 0.14);
  --border-accent: oklch(0.62 0.18 238 / 0.5);
  --border-error: oklch(0.52 0.24 5 / 0.5);

  --accent: oklch(0.58 0.2 238);
  --accent-hover: oklch(0.52 0.21 238);
  --accent-muted: oklch(0.58 0.2 238 / 0.12);
  --accent-foreground: oklch(0.99 0 0);

  --success: oklch(0.58 0.16 155);
  --warning: oklch(0.62 0.17 80);
  --error: oklch(0.52 0.24 5);
  --error-foreground: oklch(0.99 0 0);
  --info: oklch(0.58 0.16 238);

  --ring: oklch(0.62 0.18 238 / 0.5);

  --shadow-xs: 0 1px 2px 0 oklch(0 0 0 / 0.06);
  --shadow-sm:
    0 2px 4px -1px oklch(0 0 0 / 0.08), 0 1px 2px -1px oklch(0 0 0 / 0.06);
  --shadow-md:
    0 4px 8px -2px oklch(0 0 0 / 0.1), 0 2px 4px -2px oklch(0 0 0 / 0.08);
  --shadow-lg:
    0 12px 24px -8px oklch(0 0 0 / 0.12), 0 4px 8px -4px oklch(0 0 0 / 0.1);
  --shadow-glow:
    0 0 0 1px var(--border-accent),
    0 0 16px -4px color-mix(in oklab, var(--accent) 40%, transparent);
  --shadow-glow-error:
    0 0 0 1px var(--border-error),
    0 0 16px -4px color-mix(in oklab, var(--error) 40%, transparent);
  --shadow-focus: 0 0 0 2px var(--ring), 0 0 16px -4px var(--accent);
  --shadow-focus-error: 0 0 0 2px var(--error), 0 0 16px -4px var(--error);
}

/* ---------------------------------------------------------------------------
 * 2. Tailwind v4 theme mapping
 *    Utilities like bg-surface, text-foreground, border-border resolve to
 *    the variables above. Consumers override the variables, not the utilities.
 * --------------------------------------------------------------------------- */

@theme inline {
  /* Colors */
  --color-background: var(--background);
  --color-surface: var(--surface);
  --color-surface-elevated: var(--surface-elevated);
  --color-surface-hover: var(--surface-hover);
  --color-foreground: var(--foreground);
  --color-foreground-muted: var(--foreground-muted);
  --color-foreground-subtle: var(--foreground-subtle);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-border-accent: var(--border-accent);
  --color-border-error: var(--border-error);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --color-accent-muted: var(--accent-muted);
  --color-accent-foreground: var(--accent-foreground);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-error: var(--error);
  --color-error-foreground: var(--error-foreground);
  --color-info: var(--info);
  --color-ring: var(--ring);

  /* Fonts */
  --font-sans: var(--font-sans);
  --font-mono: var(--font-mono);

  /* Radius */
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-full: var(--radius-full);

  /* Shadows */
  --shadow-xs: var(--shadow-xs);
  --shadow-sm: var(--shadow-sm);
  --shadow-md: var(--shadow-md);
  --shadow-lg: var(--shadow-lg);
  --shadow-glow: var(--shadow-glow);
  --shadow-glow-error: var(--shadow-glow-error);
  --shadow-focus: var(--shadow-focus);
  --shadow-focus-error: var(--shadow-focus-error);

  /* Motion durations + easings (Tailwind v4 exposes them as utilities) */
  --duration-fast: var(--duration-fast);
  --duration-normal: var(--duration-normal);
  --duration-slow: var(--duration-slow);
  --ease-standard: var(--ease-standard);
  --ease-emphasized: var(--ease-emphasized);
  --ease-exit: var(--ease-exit);

  /* Accordion expand/collapse — syncs with Radix's --radix-accordion-content-height */
  --animate-accordion-down: accordion-down var(--duration-normal)
    var(--ease-standard);
  --animate-accordion-up: accordion-up var(--duration-normal)
    var(--ease-standard);

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

/*
 * Ionbit UI — Base layer
 *
 * Minimal reset-adjacent defaults + reduced-motion policy.
 * Import once at the application root, after tokens.css.
 */

@layer base {
  * {
    border-color: var(--border);
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    line-height: var(--leading-normal);
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  /* Reduced-motion policy: disable all animations and transitions by default.
     Components and primitives must opt in via .motion-safe for animations
     that are safe to keep (functional, non-distracting state changes). */
  @media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
      animation-duration: 0.001ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.001ms !important;
      scroll-behavior: auto !important;
    }
  }
}

/* Opt-in escape hatch for animations that are safe under reduced motion. */
@media (prefers-reduced-motion: reduce) {
  .motion-safe\:animate,
  .motion-safe\:transition {
    animation-duration: var(--duration-fast) !important;
    transition-duration: var(--duration-fast) !important;
  }
}
